 summary=h['summary'];assert summary['environment_intensity']==.75 and summary['actual_ibl_changed_pixels']==311280 and summary['near_white_rgb230_pixels']==0
 capture=owner['capture'];target=DIST/'assets/completed'/f"{capture['sha256']}.png";shutil.copy2(verified(capture['path'],capture['sha256']),target);pixels=decoded_media(target);assert pixels['frames'][0]['size']==[1151,1309]
 dest=ROOT/'Temp/gltf-validation/site-evidence/manifests'/f'{manifest}.json';shutil.copy2(path,dest)
 limits=['Diffuse transmission is enabled: LEFT half of the authored reference is relevant; RIGHT is historical core fallback. Main1151×1309 image is SOURCE ONLY; canonical192px functional proof remains separate.','Field HDRI illumination and matching actual skybox at0.75 replace bright point lights; ambient is zero. ACES exposure is fixed at1/EV0. Environment, intensity/yaw and tone settings are inferred, not upstream calibrated.','Camera pose is unchanged but projection changed from orthographic to18° vertical perspective to show the actual sky. Framing is inferred.','Five actual RTTs in each of four bounded states had four zero-delta pairs. IBL-off changed311,280 foreground pixels; deletion was black. This is not full HDR resident-texel or reference-equivalence proof.','Native diffuse BRDF and extension Lambert response differ; exact upstream lighting, exposure and appearance remain unknown. User approval is pending; prior too-bright/HDRI concern remains open until review.']
 notice='HDRI lighting correction · actual Field sky + IBL0.75; former point lights off, ACES fixed EV0. Inferred18° perspective replaces orthographic. LEFT reference half is enabled diffuse transmission. SOURCE ONLY; canonical192px proof remains separate. Prior lighting concern is open pending your review.'
 recipe=copy.deepcopy(owner['presentation_recipe']);row.update(capture={'url':str(target.relative_to(DIST)),'sha256':capture['sha256'],'kind':'image','frames':1,'duration':0},variant='Diffuse-transmission source · settled HDRI review',referenceNotice=notice,recipeApplied={'camera':{k:recipe[k]for k in ['camera_position_inches','camera_target_inches','projection','vertical_fov_degrees','near','far','width','height']},'presentation':recipe,'complete':True,'limitations':limits},recipe={'camera':{k:recipe[k]for k in ['projection','vertical_fov_degrees','width','height']},'presentation':recipe,'matchStatus':'needs-tuning','provenance':'Actual source Field skybox and IBL; fixed exposure; inferred perspective framing.','limitations':limits},whatChanged=notice,visualReview={'status':'pending','reviewer':None},compatibleReviewFingerprints=[],updated=True,visualChanged=True)
 row['evidence']=copy.deepcopy(old['evidence']);row['evidence'].update(manifestSha256=manifest,receiptSha256=h['receipt']['sha256'],scope=capture['scope'],convergence={'states':4,'actualRendersPerState':5,'maxPairDelta':0,'fixedExposure':1,'nativeTonemapActive':True},environment={'compiledDiskSha256':summary['environment_compiled_sha256'],'intensity':.75,'yaw':0,'iblChangedForegroundPixels':311280,'residentHdrByteIdentityNewlyProven':False},limitations=limits)
 row['previousCapture']={'url':old['capture']['url'],'sha256':old['capture']['sha256'],'fingerprint':old['comparisonFingerprint'],'label':'Earlier image · reported too bright ↗','notice':'v28 lighting/HDRI concern is preserved as chat-reported feedback, not a form vote. It stays open pending review of this changed comparison.'}
 row['comparisonFingerprint']=comparison_identity(row,pixels,reference_pixels(row['reference']));row['reviewGroupFingerprint']=group_identity(row,pixels,reference_pixels(row['reference']));row['provenanceFingerprint']=digest(row['evidence']);assert row['comparisonFingerprint']!=old['comparisonFingerprint']
 data.setdefault('previousComparisons',[]).append(old);assert data['previousComparisons'][-1]==old
 model=next(m for m in data['models']if m['id']=='MandarinOrange');a=h['environment_attribution'];model['licenses'].append({'license':'CC-BY-3.0','licenseUrl':a['license_url'],'artist':a['author'],'sourceUrl':a['source_url'],'what':'Field HDRI visible sky and illumination; chosen environment, not proven upstream environment.'})
 for prior in before['cases']:
  now=next(c for c in data['cases']if c['id']==prior['id'])
  if prior['id']!=caseid:assert now==prior
 assert data['savedReviews']==before['savedReviews'] and len(data['cases'])==len(before['cases'])
 feedback=read(ROOT/'research/gltf-validation/user-feedback.json');issue=next(i for i in feedback['reportedIssues']if i['id']=='mandarin-v28-lighting-chat-feedback');assert issue['comparisonFingerprint']==old['comparisonFingerprint'] and issue['status']=='open'
 queue=read(DIST/'review-queue.json');q=next(q for q in queue['queue']if q['caseId']==caseid);q.update(variant=row['variant'],comparisonFingerprint=row['comparisonFingerprint'],reviewGroupFingerprint=row['reviewGroupFingerprint'],captureSha256=capture['sha256'],check=notice,limitations=' '.join(limits),evidence=row['evidence'],savedReviewStillMatches=False,savedReview=None);q.setdefault('reportedIssues',[]).append(issue)
 write(DIST/'data.json',data);write(DIST/'review-queue.json',queue);report={'caseId':caseid,'previousFingerprint':old['comparisonFingerprint'],'newFingerprint':row['comparisonFingerprint'],'captureSha256':capture['sha256'],'receiptSha256':h['receipt']['sha256'],'manifestSha256':manifest,'priorComparisonArchivedExactly':True,'unchangedRowsPreserved':len(before['cases'])-1,'totalRows':len(data['cases']),'captured':data['summary']['captures'],'newVariantRows':0,'reportedIssueStillOpen':True,'unchangedFunctionalProofReused':True,'png16Untouched':True,'userApproval':'pending'};write(ROOT/'Temp/gltf-validation/mandarin-hdri-site-ingest.json',report);print(json.dumps(report))
